SELECT t.id, t.task_type_key, t.status, t.priority, t.retry_count, t.worker_ip, t.callback_url, t.callback_status, t.progress, t.current_step_key, t.current_step_progress, t.steps_detail, t.error_msg, t.created_at, t.updated_at, t.started_at, t.finished_at, t.expired_at, t.is_deleted, c.type_name, c.exec_timeout_sec as timeout_seconds FROM asts_task t LEFT JOIN asts_task_type_config c ON t.task_type_key = c.type_key AND c.is_deleted = 0 WHERE t.is_deleted = 0
AND t.status = #{status}
AND t.task_type_key = #{taskType}
ORDER BY t.created_at DESC

SELECT t.id, t.task_type_key, t.status, t.priority, t.retry_count, t.worker_ip, t.callback_url, t.callback_status, t.progress, t.current_step_key, t.current_step_progress, t.steps_detail, t.error_msg, t.created_at, t.updated_at, t.started_at, t.finished_at, t.expired_at, t.is_deleted, c.type_name, c.exec_timeout_sec as timeout_seconds FROM asts_task t LEFT JOIN asts_task_type_config c ON t.task_type_key = c.type_key AND c.is_deleted = 0 WHERE 1=1
AND t.is_deleted = 1
AND t.is_deleted = 0
AND t.id = #{id}
AND t.status = #{status}
AND t.task_type_key = #{taskType}
AND t.created_at >= #{createdAtStart}
AND t.created_at <= #{createdAtEnd}
ORDER BY t.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM asts_task t
WHERE 1=1


        AND t.is_deleted = 1


        AND t.is_deleted = 0






    AND t.id = #{id}


    AND t.status = #{status}


    AND t.task_type_key = #{taskType}


    AND t.created_at >= #{createdAtStart}


    AND t.created_at <= #{createdAtEnd}
